      "slo_id": "S2",
      "level": "understand",
      "question": "Which statement correctly describes the zero exponent rule?",
      "options": [
        "Any non-zero number raised to the power of zero is 1.",
        "Any number raised to the power of zero is 0.",
        "Any number raised to the power of zero is the number itself."
      ],
      "correct_index": 0,
      "explanation": "The zero exponent rule states that any non-zero base raised to the power of zero always equals 1.",
      "selected_because": "The definition of the zero exponent rule.",
      "distractor_misconceptions": {
        "1": "Confuses zero exponent with multiplication by zero.",
        "2": "Believes zero exponent leaves the base unchanged."
      },
      "option_feedback": {
        "correct": "That's right! The zero exponent rule tells us that any non-zero number raised to the power of zero is always 1.",
        "wrong": {
          "1": "Not quite. When a number is raised to the power of zero, the result is 1, not 0. Remember, $5^2 \\div 5^2$ equals 1, and it also equals $5^0$.",
          "2": "That's not correct. A zero exponent does not leave the number as it is. For example, $5^0$ is 1, not 5."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Simplify expressions with a power raised to a power, a zero exponent and a negative exponent.",
      "teaching_error": null
    }
  ]
